import{_ as a,c as n,o as t,ah as s}from"./chunks/framework.CdwlI3v5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"WhiteHats CTF 2021","chal":"Secure Banking","category":"crypto","flag":"WH2021{$m00000n3y_g0_Burrrrrrrrrrrrrrr}","points":986,"solves":9},"headers":[],"relativePath":"writeups/2021/WhiteHats 2021/Secure Banking/2021-03-07-Secure Banking.md","filePath":"writeups/2021/WhiteHats 2021/Secure Banking/2021-03-07-Secure Banking.md"}'),i={name:"writeups/2021/WhiteHats 2021/Secure Banking/2021-03-07-Secure Banking.md"};function r(o,e,l,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s(`<blockquote><p>Your friend Peter has built a new online transaction and banking service called AAA Banking. He claims it is extremely secure, using SHA256 hashing to create and verify HMACs. To get you onto the platform, he has sent you $20 for free! Try it out now! Check out the [platform](AAA Secure Banking.html)!</p></blockquote><blockquote><p>You are given the following details:</p></blockquote><blockquote><pre><code>Details: \`ZnJvbT1QZXRlciZhbW91bnQ9MjA=\`
</code></pre></blockquote><blockquote><pre><code>Verification Hash: \`24a2efde8a32e7046aaeb11eb32a37ecf49937ef84c7a6b4bd943556fd2369cd\`
</code></pre></blockquote><blockquote><p>However, as a White Hacker, you are obviously sceptical of such a website.</p></blockquote><blockquote><p>Knowing that your friend is also an Admin and has over millions of dollars, can you get him to send you a million dollars as Admin?</p></blockquote><blockquote><p>Note: You DO NOT need any form of brute force or directory busting to complete this challenge!</p></blockquote><p>Visiting the website, we see that the hash is generated by prepending a secret in front of the details with a 19 byte secret. This is precisely the usual setup for a length extension attack. Decoding the details as base64, we see it is <code>from=Peter&amp;amount=20</code>, hence we likely want to append <code>&amp;from=Admin&amp;amount=1000000</code>.</p><p>Running <a href="https://github.com/iagox86/hash_extender" target="_blank" rel="noreferrer">hash_extender</a>, we get</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; ./hash_extender --data &quot;from=Peter&amp;amount=20&quot; --append &quot;&amp;from=Admin&amp;amount=1000000&quot; --signature 24a2efde8a32e7046aaeb11eb32a37ecf49937ef84c7a6b4bd943556fd2369cd --format sha256 --secret 19</span></span>
<span class="line"><span>Type: sha256</span></span>
<span class="line"><span>Secret length: 19</span></span>
<span class="line"><span>New signature: 3ac04e9e4a435072edf4961702a6eddb9cf52a3387019006119d05af98a17ebc</span></span>
<span class="line"><span>New string: 66726f6d3d506574657226616d6f756e743d3230800000000000000000000000000000000000000000000001382666726f6d3d41646d696e26616d6f756e743d31303030303030</span></span></code></pre></div><p>and by submitting these values with the proper encoding, we get the flag.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Transaction Confirmed!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Congrats! Heres your flag!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WH2021{$m00000n3y_g0_Burrrrrrrrrrrrrrr}</span></span></code></pre></div>`,12)])])}const g=a(i,[["render",r]]);export{h as __pageData,g as default};
